using Godot;
using System;
using System.Linq;
using Settings=Godot.Collections.Dictionary;

public partial class WorldUiOperations
{
    private static Control Canvas(Control owner)=>owner.Get("canvas").As<Control>();
    private static GodotObject RoadTool(Control owner)=>Canvas(owner).Get("road_tool").AsGodotObject();
    private static void EditedResult(Control owner,string id,Settings result,string label,bool joined=false)
    {var next=Get(result,"source").As<Resource>();if(next==null)owner.Get("status").As<Label>().Text=result["error"].AsString();else{if(joined)owner.SetMeta("world_road_index",result["index"]);Apply(owner,id,next,label);}}
    private void Roads(Control owner,Resource item,Resource source,Node parent,string[] types)
    {
        string id=item.Get("id").AsString();var roads=source.Get("roads").AsGodotArray();int index=Math.Clamp(owner.GetMeta("world_road_index",0).AsInt32(),0,Math.Max(0,roads.Count-1));Choice(owner,parent,roads.Select(value=>Get(value.AsGodotDictionary(),"name","Road").AsString()).ToArray(),index,next=>{owner.SetMeta("world_road_index",next);var tool=RoadTool(owner);tool.Set("road_index",next);tool.Set("point_index",0);owner.Call("_refresh_properties");});if(roads.Count==0)return;var road=roads[index].AsGodotDictionary();parent.AddChild(new Label {Text="━ "+Get(road,"name","Road").AsString()});
        Choice(owner,parent,types,Math.Max(0,Array.IndexOf(types,Get(road,"type","Residential Street").AsString())),value=>ModifyEntry(owner,id,"roads",index,next=>next.Merge(new RoadSectionOperations().defaults(types[value]),true),"Change road type"));var modes=new[]{"Ground","Bridge","Tunnel"};Choice(owner,parent,modes,Math.Max(0,Array.IndexOf(modes,Get(road,"mode","Ground").AsString())),value=>ModifyEntry(owner,id,"roads",index,next=>next["mode"]=modes[value],"Change road crossing"));
        Value(owner,parent,"Elevation",road["points"].AsVector3Array()[0].Y,-1000,1000,.1,value=>Modify(owner,id,next=>{var entries=next.Get("roads").AsGodotArray();if(index>=entries.Count)return;var entry=entries[index].AsGodotDictionary();var points=entry["points"].AsVector3Array();double offset=value-points[0].Y;for(int point=0;point<points.Length;point++)points[point]+=Vector3.Up*(float)offset;entry["points"]=points;entry["follow_terrain"]=false;var nodes=next.Get("nodes").AsGodotDictionary();nodes[entry["from"]]=points[0];nodes[entry["to"]]=points[^1];},"Set road elevation"));
        string mode=Get(road,"mode","Ground").AsString();if(mode=="Ground")Toggle(owner,parent,"Follow terrain",Get(road,"follow_terrain",false).AsBool(),on=>ModifyEntry(owner,id,"roads",index,next=>next["follow_terrain"]=on,"Change terrain following"));if(mode=="Bridge")Value(owner,parent,"Pier height",Get(road,"pier_height",8.0).AsDouble(),.3,100,.1,value=>ModifyEntry(owner,id,"roads",index,next=>next["pier_height"]=value,"Change bridge supports"));Value(owner,parent,"Width",road["width"].AsDouble(),.5,40,.25,value=>ModifyEntry(owner,id,"roads",index,next=>next["width"]=value,"Change road width"));
        Toggle(owner,parent,"Road section details",Get(road,"section",false).AsBool(),on=>ModifyEntry(owner,id,"roads",index,next=>{next.Merge(new RoadSectionOperations().defaults("Residential Street"));next["section"]=on;},"Toggle road section details"));if(Get(road,"section",false).AsBool())
        {
            foreach(var spec in new[]{("Thickness","thickness",0.0,2.0,.01),("Shoulder width","shoulder",0.0,8.0,.1),("Sidewalk width","sidewalk",0.0,8.0,.1),("Curb height","curb_height",0.0,.5,.01),("Lanes","lanes",1.0,12.0,1.0),("Speed limit","speed_limit",0.0,200.0,5.0)})Value(owner,parent,spec.Item1,Get(road,spec.Item2,0.0).AsDouble(),spec.Item3,spec.Item4,spec.Item5,value=>ModifyEntry(owner,id,"roads",index,next=>next[spec.Item2]=spec.Item2=="lanes"?Variant.From((int)value):Variant.From(value),"Change road "+spec.Item2));foreach(string field in new[]{"markings","one_way"})Toggle(owner,parent,field=="markings"?"Lane markings":"One way",Get(road,field,false).AsBool(),on=>ModifyEntry(owner,id,"roads",index,next=>next[field]=on,"Change road "+field));
        }
        var fitting=new HBoxContainer();parent.AddChild(fitting);foreach(string caption in new[]{"Fit terrain","Route around hills"})Button(owner,fitting,caption,()=>{var current=Source(owner,id);if(current!=null)EditedResult(owner,id,new WorldTerrainOperations().fit(Session(owner),id,current,index,caption=="Route around hills"),"Fit road to terrain");});
        var operations=new HFlowContainer();parent.AddChild(operations);foreach(string caption in new[]{"Reverse","Split","Delete point","Extend"})Button(owner,operations,caption,()=>
        {
            var current=Source(owner,id);if(current==null||index>=current.Get("roads").AsGodotArray().Count)return;var canvas=Canvas(owner);var tool=RoadTool(owner);if(caption=="Extend"){canvas.Set("environment_tool","Draw road");tool.Set("_world_id",id);tool.Set("_first",current.Get("roads").AsGodotArray()[index].AsGodotDictionary()["points"].AsVector3Array()[^1]);tool.Set("_hover",default);canvas.GrabFocus();canvas.Get("overlay").As<CanvasItem>().QueueRedraw();return;}int point=tool.Get("road_index").AsInt32()==index?tool.Get("point_index").AsInt32():-1;var editing=new RoadEditingOperations();var result=caption=="Reverse"?editing.reverse(current,index):caption=="Split"?editing.split(current,index,point):editing.remove_point(current,index,point);EditedResult(owner,id,result,caption+" road");
        });
        var joining=new MenuButton {Text="Join endpoint to road…",Disabled=roads.Count<2};parent.AddChild(joining);for(int other=0;other<roads.Count;other++)if(other!=index)joining.GetPopup().AddItem(Get(roads[other].AsGodotDictionary(),"name","Road").AsString(),other);joining.GetPopup().IdPressed+=other=>{if(!Fresh(joining,owner))return;var current=Source(owner,id);if(current!=null)EditedResult(owner,id,new RoadEditingOperations().join(current,index,(int)other),"Join roads",true);};Button(owner,parent,"Remove road",()=>Modify(owner,id,next=>{var values=next.Get("roads").AsGodotArray();if(index<values.Count)values.RemoveAt(index);},"Remove road"));
    }
}
